"use strict";(globalThis.webpackChunklearngenomics_dev||=[]).push([[6289],{2325(e,n,a){a.r(n),a.d(n,{assets:()=>c,contentTitle:()=>l,default:()=>f,frontMatter:()=>h,metadata:()=>r,toc:()=>d});var i=a.cw((e,n)=>{const i=a.p+"assets/images/2.10-germline-second-hit-dark-ff6602f856fbb85cfd2a30e6deff79ee.svg";a.d(n,["A",0,i])}),t=a.cw((e,n)=>{const i=a.p+"assets/images/2.10-germline-second-hit-cdbbf910b21ea27481f0fc95c89ca1a5.svg";a.d(n,["A",0,i])});const r=JSON.parse('{"id":"cancer-biology/inherited-risk","title":"Inherited Risk","description":"How inherited germline variants raise cancer risk, well-known predisposition syndromes, predisposition in childhood cancer, and how to find it in data.","source":"@site/docs/02-cancer-biology/06-inherited-risk.md","sourceDirName":"02-cancer-biology","slug":"/cancer-biology/inherited-risk","permalink":"/docs/cancer-biology/inherited-risk","draft":false,"unlisted":false,"editUrl":"https://github.com/stjude/learngenomics.dev/tree/main/docs/02-cancer-biology/06-inherited-risk.md","tags":[],"version":"current","sidebarPosition":6,"frontMatter":{"title":"Inherited Risk","description":"How inherited germline variants raise cancer risk, well-known predisposition syndromes, predisposition in childhood cancer, and how to find it in data."},"sidebar":"tutorialSidebar","previous":{"title":"How Tumors Evolve","permalink":"/docs/cancer-biology/how-tumors-evolve"},"next":{"title":"Introduction","permalink":"/docs/genomic-variation/introduction"}}');var o=a(4848),s=a(8453);const h={title:"Inherited Risk",description:"How inherited germline variants raise cancer risk, well-known predisposition syndromes, predisposition in childhood cancer, and how to find it in data."},l=void 0,c={},d=[{value:"The Second Hit",id:"the-second-hit",level:2},{value:"Well-Known Syndromes",id:"well-known-syndromes",level:2},{value:"Predisposition in Childhood Cancer",id:"predisposition-in-childhood-cancer",level:2},{value:"Common Variants, Small Effects",id:"common-variants-small-effects",level:2},{value:"Finding Them in the Data",id:"finding-them-in-the-data",level:2},{value:"Up Next",id:"up-next",level:2}];function m(e){const n={a:"a",em:"em",figcaption:"figcaption",figure:"figure",h2:"h2",img:"img",li:"li",p:"p",span:"span",strong:"strong",ul:"ul",...(0,s.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsxs)(n.p,{children:["Most of the mutations behind a cancer arise during a person's lifetime, in the cells\nthat become the tumor. Some people, though, start life with a germline variant that\nraises their risk of cancer. A variant passed down in an egg or sperm is in every cell\nof the body. One that arises after fertilization is passed only to the cells that\ndescend from the cell where it arose. Having cells with different genomes in one body is\ncalled ",(0,o.jsx)(n.strong,{children:"mosaicism"}),", and it can start in the first days of development or later\n(",(0,o.jsx)(n.a,{href:"https://www.genome.gov/genetics-glossary/Mosaicism",children:"National Human Genome Research\nInstitute"}),"). About 5\u201310% of all\ncancers are thought to be caused by harmful variants inherited from a parent (",(0,o.jsx)(n.a,{href:"https://www.cancer.gov/about-cancer/causes-prevention/genetics/genetic-testing-fact-sheet",children:"National\nCancer\nInstitute"}),")."]}),"\n",(0,o.jsxs)(n.p,{children:["Such a variant creates a ",(0,o.jsx)(n.strong,{children:"predisposition"})," to cancer. It raises the odds, and some\ncarriers never develop cancer at all. How likely a carrier is to develop the disease is\nthe variant's ",(0,o.jsx)(n.strong,{children:"penetrance"}),", and it differs widely from gene to gene."]}),"\n",(0,o.jsx)(n.h2,{id:"the-second-hit",children:"The Second Hit"}),"\n",(0,o.jsxs)(n.p,{children:["Most of the genes behind inherited risk are tumor suppressors. As ",(0,o.jsx)(n.a,{href:"/docs/cancer-biology/oncogenes-and-tumor-suppressors#two-hits",children:"Two\nHits"})," explained, many tumor suppressors\nstop holding a cell back only when both copies are lost. A person who inherits one\nbroken copy starts with every cell one step along, and a tumor often begins when one of\nthose cells loses the working copy. In tumors from 10,389 adults with 33 kinds of\ncancer, 8% of patients carried a germline variant that predisposed them to cancer. In\ntumor suppressors, 43% of these variants showed signs of a second hit in the tumor,\nusually loss of the working copy. A smaller number were in oncogenes such as ",(0,o.jsx)(n.em,{children:"MET"})," and\n",(0,o.jsx)(n.em,{children:"RET"}),", and these genes tended to be more highly expressed (",(0,o.jsx)(n.a,{href:"https://doi.org/10.1016/j.cell.2018.03.039",children:"Huang et al.,\n2018"}),")."]}),"\n",(0,o.jsxs)(n.p,{children:["The second hit leaves a mark in sequencing data. In a normal sample from a carrier, each\ncell has two copies of the gene, one with the variant and one that works. Reads come\nfrom both copies about equally, so roughly half of the reads at that position show the\nvariant. The share wobbles a little above or below 50% by chance, and it can be well\nbelow 50% when the variant is mosaic. One way a tumor loses the working copy is\n",(0,o.jsx)(n.a,{href:"/docs/genomic-variation/copy-number-variation#allele-fractions",children:"copy-neutral loss of\nheterozygosity"}),",\nwhich replaces it with a second copy of the broken one. Every read from a tumor cell\nthen shows the variant, and in a sample that is 60% tumor, about 80% of all reads do\n(Figure 2.10)."]}),"\n",(0,o.jsxs)(n.figure,{className:"lg-figure lg-figure--themed",id:"figure-2-10",children:[(0,o.jsx)(n.img,{alt:"Two rows of ten cells, each cell holding two copies of a gene. In the normal sample, every cell has one working copy and one copy with an inherited variant, and a bar below shows 10 of 20 copies, or about 50% of reads, carrying the variant. In the tumor sample, six of the ten cells are tumor cells with two copies of the variant and no working copy, and four are normal cells like those above. The bar below shows 16 of 20 copies, or about 80% of reads, carrying the variant.",src:t().A+"",width:"392",height:"396"}),(0,o.jsx)(n.img,{className:"lg-figure__dark",src:i().A,alt:"Two rows of ten cells, each cell holding two copies of a gene. In the normal sample, every cell has one working copy and one copy with an inherited variant, and a bar below shows 10 of 20 copies, or about 50% of reads, carrying the variant. In the tumor sample, six of the ten cells are tumor cells with two copies of the variant and no working copy, and four are normal cells like those above. The bar below shows 16 of 20 copies, or about 80% of reads, carrying the variant.",width:"392",height:"396",loading:"lazy",decoding:"async"}),(0,o.jsxs)(n.figcaption,{children:[(0,o.jsx)(n.span,{className:"lg-figure__number",children:"Figure 2.10"})," An inherited variant in normal and tumor samples. Every cell in the body carries the variant on one copy, so about half of the reads from a normal sample show it. Here the tumor cells have lost the working copy and copied the one with the variant in its place. In a sample that is 60% tumor, about 80% of the reads show the variant. The data are made up."]})]}),"\n",(0,o.jsx)(n.h2,{id:"well-known-syndromes",children:"Well-Known Syndromes"}),"\n",(0,o.jsx)(n.p,{children:"A predisposition that runs in families and follows a recognizable pattern is called a\nhereditary cancer syndrome. A few are especially well studied. In most of them, a person\nis born with one broken copy of a gene in every cell, and the other copy still works.\nConstitutional mismatch repair deficiency is the exception, because it starts with two\nbroken copies."}),"\n",(0,o.jsxs)(n.ul,{children:["\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Li-Fraumeni syndrome"})," (",(0,o.jsx)(n.em,{children:"TP53"}),"). Carriers develop many kinds of cancer, often young,\nincluding breast cancer, sarcomas and brain tumors. In 286 carriers, half of the women\nhad developed cancer by age 31 and half of the men by 46, and nearly all by age 70.\nAbout half of those who had one cancer went on to develop another (",(0,o.jsx)(n.a,{href:"https://doi.org/10.1002/cncr.30248",children:"Mai et al.,\n2016"}),")."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Hereditary breast and ovarian cancer"})," (",(0,o.jsx)(n.em,{children:"BRCA1"})," and ",(0,o.jsx)(n.em,{children:"BRCA2"}),"). Among nearly 10,000\nwomen who carried a variant in one of these genes, the risk of breast cancer by age 80\nwas 72% for ",(0,o.jsx)(n.em,{children:"BRCA1"})," and 69% for ",(0,o.jsx)(n.em,{children:"BRCA2"}),". The risk of ovarian cancer was 44% and 17%\n(",(0,o.jsx)(n.a,{href:"https://doi.org/10.1001/jama.2017.7112",children:"Kuchenbaecker et al., 2017"}),")."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Lynch syndrome"})," (",(0,o.jsx)(n.em,{children:"MLH1"}),", ",(0,o.jsx)(n.em,{children:"MSH2"}),", ",(0,o.jsx)(n.em,{children:"MSH6"})," and ",(0,o.jsx)(n.em,{children:"PMS2"}),"). These are ",(0,o.jsx)(n.a,{href:"/docs/cancer-biology/oncogenes-and-tumor-suppressors#genes-that-guard-the-genome",children:"mismatch\nrepair"})," genes, and\nabout 1 in 279 people carries a harmful variant in one of them (",(0,o.jsx)(n.a,{href:"https://doi.org/10.1158/1055-9965.EPI-16-0693",children:"Win et al.,\n2017"}),"). The risk depends on the gene.\nCarriers of ",(0,o.jsx)(n.em,{children:"MLH1"})," and ",(0,o.jsx)(n.em,{children:"MSH2"})," variants have high risks of colorectal, endometrial and\novarian cancer, ",(0,o.jsx)(n.em,{children:"MSH6"})," variants mainly raise the risk of endometrial cancer, and a\nlarge study found no clear rise in risk for ",(0,o.jsx)(n.em,{children:"PMS2"})," (",(0,o.jsx)(n.a,{href:"https://doi.org/10.1038/s41436-019-0596-9",children:"Dominguez-Valentin et al.,\n2020"}),")."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Constitutional mismatch repair deficiency."})," A child who inherits a broken copy of\nthe same mismatch repair gene from both parents has no working copy in any cell.\nCancers start in childhood, mainly in the blood, the brain and the intestines (",(0,o.jsx)(n.a,{href:"https://doi.org/10.1136/jmedgenet-2014-102284",children:"Wimmer\net al., 2014"}),")."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Heritable retinoblastoma"})," (",(0,o.jsx)(n.em,{children:"RB1"}),"). This is the case that led to the ",(0,o.jsx)(n.a,{href:"/docs/cancer-biology/oncogenes-and-tumor-suppressors#two-hits",children:"two-hit\nmodel"}),". About 25\u201330% of\nretinoblastomas are heritable, but only about a quarter of these children have a\nparent who had the disease. In the rest, the ",(0,o.jsx)(n.em,{children:"RB1"})," variant arose new, in a sperm or\negg cell or early in development (",(0,o.jsx)(n.a,{href:"https://www.cancer.gov/types/retinoblastoma/hp/retinoblastoma-treatment-pdq",children:"National Cancer\nInstitute"}),").\nBecause every cell carries the broken copy, the risk doesn't end with the eye. Among\n1,128 survivors of heritable retinoblastoma, 33.1% had developed another cancer within\n50 years, with especially high risks of sarcomas and raised risks of melanoma and\nbreast cancer. Survivors of the nonheritable form showed no rise in risk (",(0,o.jsx)(n.a,{href:"https://doi.org/10.1038/s41416-020-01248-y",children:"Schonfeld\net al., 2021"}),"). In one study of survivors\nof the heritable form, those who'd had radiation treatment for the eye tumor had about\nthree times the risk of these later cancers (",(0,o.jsx)(n.a,{href:"https://doi.org/10.1200/JCO.2005.05.054",children:"Kleinerman et al.,\n2005"}),")."]}),"\n"]}),"\n",(0,o.jsx)(n.h2,{id:"predisposition-in-childhood-cancer",children:"Predisposition in Childhood Cancer"}),"\n",(0,o.jsxs)(n.p,{children:["In children with cancer, these variants are more common than once thought. When the\ngenomes or exomes of 1,120 children and adolescents with cancer were sequenced, 8.5%\ncarried a germline variant judged harmful in a predisposition gene, compared with 1.1%\nof people without known cancer. ",(0,o.jsx)(n.em,{children:"TP53"})," was by far the most common, in 50 patients,\nfollowed by ",(0,o.jsx)(n.em,{children:"APC"}),", ",(0,o.jsx)(n.em,{children:"BRCA2"}),", ",(0,o.jsx)(n.em,{children:"NF1"}),", ",(0,o.jsx)(n.em,{children:"PMS2"}),", ",(0,o.jsx)(n.em,{children:"RB1"})," and ",(0,o.jsx)(n.em,{children:"RUNX1"}),". Of the 58 carriers whose\nfamily history was known, only 23 (40%) had relatives with cancer (",(0,o.jsx)(n.a,{href:"https://doi.org/10.1056/NEJMoa1508054",children:"Zhang et al.,\n2015"}),"). A later study found more. In 309 children\nsequenced at diagnosis or relapse, 18% carried a variant that predisposed them to\ncancer, and the tumor data suggested a role in the tumor for 55% of the harmful germline\nvariants (",(0,o.jsx)(n.a,{href:"https://doi.org/10.1158/2159-8290.CD-20-1631",children:"Newman et al., 2021"}),")."]}),"\n",(0,o.jsxs)(n.p,{children:["Why would most of these children have no relatives with cancer? The variant's penetrance\nmay be low, or the variant may be new. Among 336 people with Li-Fraumeni syndrome, at\nleast 14% of the ",(0,o.jsx)(n.em,{children:"TP53"})," variants had arisen new in the person, and the authors estimate\nthat about a fifth of these arose during embryonic development, leaving a mosaic variant\ncarried by only some of the body's cells (",(0,o.jsx)(n.a,{href:"https://doi.org/10.1136/jmedgenet-2017-104976",children:"Renaux-Petel et al.,\n2018"}),")."]}),"\n",(0,o.jsx)(n.h2,{id:"common-variants-small-effects",children:"Common Variants, Small Effects"}),"\n",(0,o.jsxs)(n.p,{children:["The variants above are rare, and many of them raise risk sharply. Inherited risk also\ncomes from many common variants that each raise it a little. These are found by\n",(0,o.jsx)(n.a,{href:"/docs/genomic-variation/single-nucleotide-variation#linking-snvs-to-disease",children:"genome-wide association\nstudies"}),",\nand their small effects can be added up into a ",(0,o.jsx)(n.strong,{children:"polygenic risk score"}),". A score built\nfrom 313 variants, using data from women of European ancestry, gave the 1% of women with\nthe highest scores an estimated lifetime risk of breast cancer of 32.6% (",(0,o.jsx)(n.a,{href:"https://doi.org/10.1016/j.ajhg.2018.11.002",children:"Mavaddat et\nal., 2019"}),")."]}),"\n",(0,o.jsx)(n.h2,{id:"finding-them-in-the-data",children:"Finding Them in the Data"}),"\n",(0,o.jsxs)(n.p,{children:["An inherited variant shows up in a tumor's data, where it can look like a change that\narose in the tumor. The clearest way to tell the two apart is to sequence a ",(0,o.jsx)(n.a,{href:"/docs/genomic-variation/baselines-for-variation#a-second-baseline-the-persons-own-dna",children:"matched\nnormal"}),"\nalongside the tumor. In 815 patients with 15 kinds of cancer, the matched normal\nrevealed germline variants in predisposition genes in 3% of patients whose cancers\nshowed no sign of being inherited. Without it, the analysis couldn't tell for certain\nwhich changes in these genes were inherited, and it added false findings that made up\n31% of the changes in a targeted panel and 65% in exomes (",(0,o.jsx)(n.a,{href:"https://doi.org/10.1126/scitranslmed.aaa7161",children:"Jones et al.,\n2015"}),")."]}),"\n",(0,o.jsxs)(n.p,{children:["An inherited variant can be relevant to a patient's cancer, and their relatives may\ncarry it too. Studies have compared testing every patient with testing only those whose\ncancer or family history points to an inherited cause. Among 2,984 adults with cancer\nwho were all tested, whatever their cancer type, age or family history, 13.3% carried a\nharmful germline variant. In 6.4%, the variant wouldn't have been found under the usual\ncriteria for deciding who to test (",(0,o.jsx)(n.a,{href:"https://doi.org/10.1001/jamaoncol.2020.6252",children:"Samadder et al.,\n2021"}),")."]}),"\n",(0,o.jsxs)(n.p,{children:["Researchers have also followed carriers over time. In a study of 89 carriers from\nfamilies with Li-Fraumeni syndrome, 59 had regular scans and tests at some point, which\nfound 40 tumors in 19 of them before the tumors caused symptoms (",(0,o.jsx)(n.a,{href:"https://doi.org/10.1016/S1470-2045(16)30249-2",children:"Villani et al.,\n2016"}),")."]}),"\n",(0,o.jsx)(n.h2,{id:"up-next",children:"Up Next"}),"\n",(0,o.jsxs)(n.p,{children:["This chapter followed cancer from the genes that drive it to the ways a tumor changes as\nit grows. The rest of this guide is about finding those changes in data. ",(0,o.jsx)(n.a,{href:"/docs/genomic-variation/introduction",children:"Genomic\nVariation"})," starts with the kinds of variants\nyou'll find and the baselines they're measured against."]})]})}function f(e={}){const{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,o.jsx)(n,{...e,children:(0,o.jsx)(m,{...e})}):m(e)}},8453(e,n,a){a.d(n,{R:()=>o,x:()=>s});var i=a(6540);const t={},r=i.createContext(t);function o(e){const n=i.useContext(r);return i.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function s(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:o(e.components),i.createElement(r.Provider,{value:n},e.children)}}}]);